('P001', 'SecurX Sentinel Pro S1', 'Security System', 'SecurX', 14500000, 16000000, NULL, 14500000, 'Sistem alarm keamanan cerdas terintegrasi dengan hub nirkabel, sensor gerak presisi tinggi, dan deteksi intrusi waktu nyata dengan cadangan baterai 24 jam.', json('["Hub Nirkabel Frekuensi Ganda", "3x Sensor Gerak PIR", "Keamanan Cadangan Baterai 24 Jam", "Integrasi Aplikasi Seluler & Cloud", "Kecepatan Respons < 1 Detik"]'), json('["https://placehold.co/1000x1000/eeeeee/050b14?text=SecurX+Sentinel+Hub", "https://placehold.co/1000x1000/dddddd/050b14?text=Sentinel+PIR+Sensor", "https://placehold.co/1000x1000/cccccc/050b14?text=Sentinel+Key+Fob"]'), 'https://cdn.pixabay.com/video/2024/11/05/240062_tiny.mp4'),
('P002', 'SpectraVision AI Dome 4K', 'CCTV', 'SpectraVision', 3750000, 4250000, NULL, 3750000, 'Kamera CCTV Dome luar ruangan ultra HD 4K dengan pengenalan wajah bertenaga AI, penglihatan malam inframerah berwarna, dan casing tahan air IP67.', json('["Resolusi Ultra HD 4K (8MP)", "Pengenalan Wajah & Manusia AI", "Color Night Vision (hingga 30m)", "IP67 Weatherproof Rating", "Dukungan PoE & Penyimpanan MicroSD"]'), json('["https://placehold.co/1000x1000/eeeeee/050b14?text=SpectraVision+Dome", "https://placehold.co/1000x1000/dddddd/050b14?text=SpectraVision+AI+Lens", "https://placehold.co/1000x1000/cccccc/050b14?text=SpectraVision+Mount"]'), 'https://cdn.pixabay.com/video/2025/12/07/320453_tiny.mp4'),
('P003', 'GateKeep BioTouch Pro X', 'Access Control', 'GateKeep', 8500000, 9800000, NULL, 8500000, 'Sistem kontrol akses pintu biometrik sidik jari dan identifikasi wajah super cepat dengan enkripsi RFID tingkat lanjut untuk keamanan gedung korporat.', json('["Pemindai Sidik Jari Optik 3D", "Identifikasi Wajah AI 0.2 Detik", "Pembaca Kartu RFID Mifare (13.56MHz)", "Kapasitas 10.000 Pengguna", "Konektivitas TCP/IP & Wi-Fi"]'), json('["https://placehold.co/1000x1000/eeeeee/050b14?text=GateKeep+BioTouch", "https://placehold.co/1000x1000/dddddd/050b14?text=GateKeep+FaceID", "https://placehold.co/1000x1000/cccccc/050b14?text=GateKeep+RFID+Reader"]'), 'https://cdn.pixabay.com/video/2025/08/24/299518_tiny.mp4'),
('P004', 'ConnectLink Pro 24X PoE Switch', 'IT Peripheral', 'ConnectLink', 6200000, 7000000, NULL, 6200000, 'Managed network switch Gigabit 24-Port dengan dukungan PoE+ penuh untuk menyalurkan daya pada CCTV, IP Phone, dan Access Point dengan kinerja tinggi.', json('["24x Port RJ45 10/100/1000Mbps", "Dukungan IEEE 802.3at/af PoE+", "Switching Capacity 52 Gbps", "Total Power Budget 370W", "Fungsi L2+ Managed Switch"]'), json('["https://placehold.co/1000x1000/eeeeee/050b14?text=ConnectLink+Switch", "https://placehold.co/1000x1000/dddddd/050b14?text=ConnectLink+Ports", "https://placehold.co/1000x1000/cccccc/050b14?text=ConnectLink+Bracket"]'), 'https://cdn.pixabay.com/video/2018/03/09/14900-259623335_tiny.mp4');
